<script setup>import { computed, ref } from 'vue'; import ZhihuPanel from './ZhihuPanel.vue'; import WordPanel from './WordPanel.vue'; import GrammarPanel from './GrammarPanel.vue'; import TranslationPanel from './TranslationPanel.vue'; import KnowledgePanel from './KnowledgePanel.vue'; import ChatPanel from './ChatPanel.vue'; const props = defineProps({ selectedText: String, selectedMode: String, selectedQuestion: String, analysisResult: Object, analyzing: Boolean, results: Array, relatedQuestions: Array, loading: Boolean, error: String, article: Object }); const emit = defineEmits(['select-mode','select-question']); const tabs = [['discussion','相关讨论'],['question','相关问题'],['column','相关专栏'],['person','人物百科']]; const activeTab = ref('discussion'); const showZhihu = computed(() => props.selectedMode === 'zhihu'); const categoryResults = computed(() => props.results.filter(item => !item.category || item.category === activeTab.value)); function selectTab(tab) { activeTab.value = tab; emit('select-mode', 'zhihu') }</script>
<template><div class="knowledge-sidebar"><div class="zhihu-head"><b>知</b><strong>知乎</strong><span>从问题中看见更大的世界</span></div><div v-if="selectedText" class="exploration">当前探索：<mark>{{ selectedText }}</mark></div><div v-if="selectedQuestion" class="question-selected">已选问题：{{ selectedQuestion }}</div><div class="zhihu-tabs"><button v-for="[key,label] in tabs" :class="{ active: activeTab === key && showZhihu }" @click="selectTab(key)">{{ label }}</button></div><p v-if="analyzing" class="empty">正在分析选中文本…</p><ZhihuPanel v-else-if="showZhihu" :results="categoryResults" :loading="loading" :error="error" /><WordPanel v-else-if="selectedMode === 'word'" :selected-text="selectedText" :result="analysisResult" /><GrammarPanel v-else-if="selectedMode === 'grammar'" :selected-text="selectedText" :result="analysisResult" /><TranslationPanel v-else-if="selectedMode === 'translation'" :selected-text="selectedText" :result="analysisResult" /><ChatPanel v-else-if="selectedMode === 'chat'" :selected-text="selectedText" :article="article" /><KnowledgePanel v-else :selected-text="selectedText" :result="analysisResult" /><section class="questions"><h3>关联问题</h3><button v-for="question in relatedQuestions" :key="question.title" :class="{ selected: selectedQuestion === question.title }" @click="emit('select-question', question.title)">▣　{{ question.title }} <span>{{ question.url ? '↗' : '→' }}</span></button><p v-if="!relatedQuestions?.length" class="empty">正在生成关联问题…</p></section></div></template>
